def decrypt_circular_code(code, k):
 n=len(code)
 if k==0:return [0]*n
 extended=code*2;answer=[]
 for index in range(n):
  if k>0:answer.append(sum(extended[index+1:index+k+1]))
  else:answer.append(sum((code*2)[index+n+k:index+n]))
 return answer

